def duy_nhat(chuoi):
    chuoi.lower()
    chu_cai=[]
    tan_so=[]
    for i in chuoi:
        if i in chu_cai:
            vi_tri=chu_cai.index(i)
            tan_so[vi_tri]+=1
        else:
            chu_cai.append(i)
            tan_so.append(1)
    for j in tan_so:
        if j==1:
            vt=tan_so.index(j)
            return vt
        elif min(tan_so)>=2:
            return -1
